<script lang="ts">
 import {onMount} from 'svelte';import {api,message} from './workspace';import {renderMarkdown} from './markdown.mjs';
 export let experimentId:string;
 type Section={document_id:string;revision_id:string;title:string;doc_type:string;body:string;audience:string;group_ids:string[];updated:boolean};
 let groups:{id:string;role:string;invitation_id:string}[]=[];
 let sections:Section[]=[],busy=false,error='',saved=false,loading=true;
 async function load(){loading=true;error='';try{const result=await api.call<{sections:Section[];groups:typeof groups}>('experiment_view_settings',{id:experimentId});sections=(result?.sections||[]).map(s=>({...s,group_ids:s.group_ids||[]}));groups=(result?.groups||[]).filter(g=>g.role!=='feedback');}catch(e){error=message(e);}finally{loading=false;}}
 async function publish(){busy=true;error='';saved=false;try{await api.call('experiment_view_publish',{id:experimentId},{sections:sections.map(({document_id,revision_id,audience,group_ids})=>({document_id,revision_id,audience,group_ids}))});saved=true;await load();}catch(e){error=message(e);}finally{busy=false;}}
 onMount(()=>{void load();});
</script>
<section class="panel"><h2>Choose what your experiment viewer shows</h2><p>Give each saved section an audience. Private stays with you. Group is for members of the invitation groups you choose below. Public is for anyone with the viewer link. Public stories with a nearby feed location can also appear in nearby feeds.</p><p class="fine">These choices control the experiment viewer. Public invitation and story links have their own shared text.</p><p class="fine">Only the title and text previewed below are shared. Your private brain dump, notebook details, and other notes stay private. Saving these choices publishes a snapshot; later edits stay private until you update it here.</p>
 {#if loading}<p role="status">Loading sharing choices…</p>{:else}<fieldset disabled={busy} style="border:0;padding:0;margin:0">{#each sections as section (section.document_id)}<div class="panel"><label>{section.title}<select bind:value={section.audience} on:change={()=>saved=false}><option value="private">Private — only me</option><option value="group">Group — selected role groups</option><option value="public">Public — anyone with the link</option></select></label>{#if section.audience==='group'}<fieldset><legend>Who can see this section?</legend>{#each groups as group (group.id)}<label class="row"><input type="checkbox" bind:group={section.group_ids} value={group.id}/>{group.role} · {sections.find(s=>s.document_id===group.invitation_id)?.title||'Invitation group'}</label>{:else}<p class="fine">Create a follow, collaboration, or advisor invitation first.</p>{/each}</fieldset>{/if}<p class="fine">{section.doc_type.replaceAll('_',' ')}{section.updated?' · Edited since last shared':''}</p><details><summary>Review the saved text to share</summary><div class="invitation-body">{@html renderMarkdown(section.body)}</div></details></div>{/each}<button type="button" class="button primary" on:click={publish}>{busy?'Saving…':'Save viewer choices'}</button></fieldset><p><a class="text-link" href={`/view/?id=${experimentId}`}>Open experiment viewer ↗</a></p>{/if}{#if saved}<p class="success" role="status">Viewer choices saved.</p>{/if}{#if error}<p class="alert" role="alert">{error}</p><button type="button" class="text-button" on:click={load}>Reload sharing choices</button>{/if}
</section>
